import React, { useState, useRef, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { getUser, logout } from '../../utils/auth';

const Header = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const user = getUser();
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const dropdownRef = useRef(null);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsDropdownOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const handleLogout = () => {
    if (window.confirm('Apakah Anda yakin ingin logout?')) {
      logout();
      navigate('/login');
    }
  };

  const getNavItems = () => {
    if (!user) return [];

    const baseItems = [
      { name: 'Dashboard', path: '/user/dashboard', icon: '🏠' },
      { name: 'My Bookings', path: '/user/mybookings', icon: '📋' },
      { name: 'Buat Booking', path: '/user/booking', icon: '➕' }
    ];

    if (user.role === 'admin') {
      return [
        { name: 'Admin Dashboard', path: '/admin/dashboard', icon: '👑' },
        { name: 'Manage Bookings', path: '/admin/bookings', icon: '📊' },
        { name: 'Manage Rooms', path: '/admin/rooms', icon: '🏢' },
        { name: 'Manage Users', path: '/admin/users', icon: '👥' },
        ...baseItems
      ];
    }

    if (user.role === 'zoom_approver') {
      return [
        { name: 'Zoom Dashboard', path: '/zoom/dashboard', icon: '💻' },
        { name: 'Zoom Requests', path: '/zoom/requests', icon: '📝' },
        ...baseItems
      ];
    }

    if (user.role === 'room_approver') {
      return [
        { name: 'Room Dashboard', path: '/room/dashboard', icon: '🏢' },
        { name: 'Room Requests', path: '/room/requests', icon: '📝' },
        ...baseItems
      ];
    }

    return baseItems;
  };

  const getRoleInfo = () => {
    const roleMap = {
      admin: { label: 'Administrator', color: 'bg-purple-500', icon: '👑' },
      zoom_approver: { label: 'Zoom Approver', color: 'bg-blue-500', icon: '💻' },
      room_approver: { label: 'Room Approver', color: 'bg-green-500', icon: '🏢' },
      user: { label: 'User', color: 'bg-gray-500', icon: '👤' }
    };
    return roleMap[user?.role] || roleMap.user;
  };

  const isActivePath = (path) => {
    return location.pathname === path;
  };

  const navItems = getNavItems();
  const roleInfo = getRoleInfo();

  return (
    <header className="bg-white shadow-sm border-b border-gray-200 sticky top-0 z-50">
      <div className="px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16">
          
          {/* Logo */}
          <div className="flex items-center flex-shrink-0">
            <button 
              onClick={() => navigate('/user/dashboard')}
              className="flex items-center space-x-3 hover:opacity-80 transition-opacity"
            >
              <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center">
                <span className="text-white font-bold">🏢</span>
              </div>
              <div className="hidden sm:block">
                <h1 className="text-lg font-bold text-gray-900">BRIRoom</h1>
                <p className="text-xs text-gray-500 -mt-1">Room Management</p>
              </div>
            </button>
          </div>

          {/* Center Navigation - Hidden on mobile, shown on desktop */}
          <nav className="hidden md:flex items-center space-x-1">
            {navItems.slice(0, 3).map((item) => (
              <button
                key={item.path}
                onClick={() => navigate(item.path)}
                className={`flex items-center space-x-2 px-3 py-2 rounded-lg text-sm font-medium transition-colors ${
                  isActivePath(item.path)
                    ? 'bg-blue-600 text-white'
                    : 'text-gray-600 hover:text-gray-900 hover:bg-gray-100'
                }`}
              >
                <span>{item.icon}</span>
                <span>{item.name}</span>
              </button>
            ))}
          </nav>

          {/* Right side */}
          <div className="flex items-center space-x-3">
            
            {/* Quick Book Button */}
            <button
              onClick={() => navigate('/user/booking')}
              className="hidden lg:flex items-center space-x-2 px-3 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium rounded-lg transition-colors"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
              </svg>
              <span>Quick Book</span>
            </button>

            {/* User Menu */}
            <div className="relative" ref={dropdownRef}>
              <button
                onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                className="flex items-center space-x-2 px-2 py-2 text-sm font-medium text-gray-700 bg-white hover:bg-gray-50 rounded-lg border border-gray-200 transition-colors"
              >
                <div className={`w-7 h-7 ${roleInfo.color} rounded-lg flex items-center justify-center`}>
                  <span className="text-white text-xs">{roleInfo.icon}</span>
                </div>
                <div className="hidden sm:block text-left min-w-0">
                  <p className="text-sm font-semibold text-gray-900 truncate max-w-24">
                    {user?.name || user?.email?.split('@')[0]}
                  </p>
                  <p className="text-xs text-gray-500 truncate">{roleInfo.label}</p>
                </div>
                <svg 
                  className={`w-4 h-4 text-gray-400 transition-transform ${isDropdownOpen ? 'rotate-180' : ''}`} 
                  fill="none" 
                  stroke="currentColor" 
                  viewBox="0 0 24 24"
                >
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                </svg>
              </button>

              {/* Dropdown Menu */}
              {isDropdownOpen && (
                <div className="absolute right-0 mt-2 w-64 bg-white rounded-lg shadow-lg border border-gray-200 overflow-hidden z-50">
                  
                  {/* User Info */}
                  <div className="bg-blue-600 px-4 py-3">
                    <div className="flex items-center space-x-3">
                      <div className="w-8 h-8 bg-white bg-opacity-20 rounded-lg flex items-center justify-center">
                        <span className="text-white">{roleInfo.icon}</span>
                      </div>
                      <div className="min-w-0 flex-1">
                        <h3 className="text-white font-semibold truncate">{user?.name || user?.email}</h3>
                        <span className="inline-block px-2 py-1 bg-white bg-opacity-20 text-white text-xs rounded">
                          {roleInfo.label}
                        </span>
                      </div>
                    </div>
                  </div>

                  {/* Navigation */}
                  <div className="py-1">
                    {navItems.map((item) => (
                      <button
                        key={item.path}
                        onClick={() => {
                          navigate(item.path);
                          setIsDropdownOpen(false);
                        }}
                        className={`w-full flex items-center space-x-3 px-4 py-2 text-sm transition-colors ${
                          isActivePath(item.path)
                            ? 'bg-blue-50 text-blue-700'
                            : 'text-gray-700 hover:bg-gray-50'
                        }`}
                      >
                        <span>{item.icon}</span>
                        <span>{item.name}</span>
                        {isActivePath(item.path) && (
                          <span className="ml-auto w-2 h-2 bg-blue-600 rounded-full"></span>
                        )}
                      </button>
                    ))}
                    
                    <div className="border-t border-gray-200 mt-1 pt-1">
                      <button
                        onClick={() => {
                          navigate('/user/profile');
                          setIsDropdownOpen(false);
                        }}
                        className="w-full flex items-center space-x-3 px-4 py-2 text-sm text-gray-700 hover:bg-gray-50 transition-colors"
                      >
                        <span>⚙️</span>
                        <span>Settings</span>
                      </button>
                      
                      <button
                        onClick={handleLogout}
                        className="w-full flex items-center space-x-3 px-4 py-2 text-sm text-red-600 hover:bg-red-50 transition-colors"
                      >
                        <span>🚪</span>
                        <span>Logout</span>
                      </button>
                    </div>
                  </div>
                </div>
              )}
            </div>

            {/* Mobile menu button */}
            <button
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
              className="md:hidden p-2 rounded-lg text-gray-400 hover:text-gray-500 hover:bg-gray-100 transition-colors"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path 
                  strokeLinecap="round" 
                  strokeLinejoin="round" 
                  strokeWidth={2} 
                  d={isMobileMenuOpen ? "M6 18L18 6M6 6l12 12" : "M4 6h16M4 12h16M4 18h16"} 
                />
              </svg>
            </button>
          </div>
        </div>

        {/* Mobile Navigation */}
        {isMobileMenuOpen && (
          <div className="md:hidden border-t border-gray-200">
            <div className="py-2 space-y-1">
              {navItems.map((item) => (
                <button
                  key={item.path}
                  onClick={() => {
                    navigate(item.path);
                    setIsMobileMenuOpen(false);
                  }}
                  className={`w-full flex items-center space-x-3 px-4 py-2 text-sm transition-colors ${
                    isActivePath(item.path)
                      ? 'bg-blue-600 text-white'
                      : 'text-gray-700 hover:bg-gray-100'
                  }`}
                >
                  <span>{item.icon}</span>
                  <span>{item.name}</span>
                </button>
              ))}
              
              <div className="border-t border-gray-200 pt-2">
                <button
                  onClick={() => {
                    navigate('/user/booking');
                    setIsMobileMenuOpen(false);
                  }}
                  className="w-full flex items-center justify-center space-x-2 px-4 py-2 bg-blue-600 text-white text-sm font-medium transition-colors rounded-lg mx-2"
                >
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
                  </svg>
                  <span>Buat Booking Baru</span>
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </header>
  );
};

export default Header;
